// Guide records are localized separately because they are created dynamically.
const guideEnglish = {
"air-pollution":["Air Pollution","Air pollution happens when harmful gases, smoke, dust, or tiny particles enter the air. Traffic, industrial activity, and burning mixed waste are common sources. Notice local sources and follow trustworthy public-health advice during poor-air conditions.","Explore air quality"],
"water-pollution":["Water Pollution","Water pollution occurs when waste, sewage, oil, or harmful chemicals enter rivers, lakes, groundwater, or other water sources. Preventing pollution at the source and disposing of waste safely helps protect people and aquatic life.","Explore water quality"],
"health-impacts":["Health Impacts","Air pollution can worsen breathing problems and affect overall wellbeing. Contaminated water can carry germs or harmful substances. For health concerns or water-safety decisions, follow guidance from qualified health professionals and trusted local authorities.","Read the pollution overview"],
"causes-pollution":["Causes of Pollution","Common sources include vehicle emissions, industrial processes, dust, waste burning, plastic litter, untreated sewage, and unsafe chemical disposal. Identifying a source helps communities choose prevention steps that address the actual problem.","Explore common sources"],
"environmental-impact":["Environmental Impact","Pollution can damage natural habitats, affect wildlife, contaminate soil and water, and place pressure on ecosystems. The scale of an impact depends on the pollutant, amount, location, exposure, and local conditions.","Explore water and habitats"],
"pollution-prevention":["Pollution Prevention","Prevention starts with reducing waste, avoiding open burning, using cleaner travel options when practical, maintaining equipment, and keeping chemicals and litter out of drains and water bodies. Follow local disposal and recycling rules.","See practical actions"],
"clean-air-awareness":["Clean Air Awareness","Look for local sources such as traffic, smoke, construction dust, or waste burning. Share reliable information, reduce avoidable emissions, and consult official air-quality information when current local conditions matter.","Explore air quality"],
"safe-water-awareness":["Safe Water Awareness","Clear-looking water is not always safe to drink. Water safety depends on contaminants that may not be visible. Follow trusted local water-authority or public-health guidance and use appropriate testing when needed.","Explore water quality"],
"air-quality-charts":["Air Quality Charts","When reading an air-quality chart, check its title, location, date, pollutant, units, and source. The air-source bars on this website are illustrative examples only; they are not AQI values or real measurements.","View the illustrative air chart"],
"water-quality-charts":["Water Quality Charts","Water-quality charts may show parameters such as pH, turbidity, dissolved substances, or microbiological test results. Each parameter has a different meaning, and no single value can prove that water is safe. This website does not provide live water-test readings.","Explore water quality"],
"aqi-levels":["AQI Levels","The Air Quality Index (AQI) summarizes air pollution using a defined scale. The scale, categories, and health advice may differ by country. Always check the date, location, and official source for current readings; this website does not display live AQI.","Explore air pollution"],
"pollution-comparison":["Pollution Comparison","Comparisons are most useful when the data uses the same units, time period, location scope, and method. A larger bar does not automatically mean a greater health risk unless the metric and its context are understood.","Review the example chart"],
"interactive-graphs":["Interactive Graphs","Interactive graphs can let visitors choose categories, inspect values, or compare periods. These controls should only be used with a clearly described dataset. The current chart on this website is a static illustration, not a live graph or sensor feed.","Review the example chart"],
"environmental-statistics":["Environmental Statistics","Before sharing a statistic, check who collected it, when and where it was collected, which units were used, how many observations were included, and how the result was calculated. The survey summary on this project is manually entered and should be checked against actual responses.","Return to project overview"],
"air-vs-water":["Air vs. Water Pollution","Air pollution may spread through gases and particles in the atmosphere, while water pollution can travel through rivers, lakes, groundwater, and drainage systems. Compare the sources, routes of exposure, affected ecosystems, and prevention methods without mixing unrelated measurements.","Explore water pollution"],
"data-interpretation":["Data Interpretation","Start with the title, axes, units, source, and date. Look for patterns, unusual values, and missing context. A relationship between two variables does not by itself prove that one caused the other, and a chart may not represent every community.","Explore the example chart"],
"plant-trees":["Plant More Trees","Choose tree species that suit local conditions, plant them in appropriate places, and care for them as they grow. Protecting existing mature trees is also valuable. Trees are one part of environmental care, not a substitute for reducing pollution at its source.","Return to action cards"],
"save-water":["Save Water","Turn off taps when they are not needed, fix leaks where possible, use water thoughtfully while cleaning, and follow local advice during shortages. Small repeated habits can reduce avoidable water waste.","Explore water quality"],
"reduce-plastic":["Reduce Plastic","Carry reusable items when practical, avoid unnecessary single-use packaging, reuse suitable containers, and separate waste according to local collection rules. Keep plastic litter away from drains and water bodies.","Explore water pollution"],
"public-transport":["Use Public Transport","Buses, trains, shared rides, walking, and cycling can reduce emissions per person when practical, accessible, and safe. Choose options that suit the route and local conditions.","Explore air pollution"],
"clean-water-sources":["Keep Water Sources Clean","Never dump oils, chemicals, medicines, or litter into drains, streams, ponds, or rivers. Use the correct local collection and disposal routes and report pollution to the appropriate local authority.","Explore water pollution"],
"spread-awareness":["Spread Awareness","Share information from trustworthy sources, explain simple prevention steps, and invite others to join environmental activities. Avoid forwarding unverified pollution statistics or presenting illustrative values as real measurements.","Return to project overview"],
"cleanup-drives":["Join Clean-Up Drives","Join an organized community clean-up, follow the organizer's safety instructions, wear suitable protection, and do not handle unknown chemicals, sharp objects, or hazardous waste. Ask the local authority how collected waste should be managed.","Return to action cards"],
"eco-pledge":["Take an Eco-Pledge","Choose one realistic action to try this week, such as saving water, using a reusable bottle, or sharing trusted environmental information. The form below is a local demonstration and does not send or store responses.","Make your eco-pledge"]
};
function getGuide(topic, lang) {
    const en = guideEnglish[topic];
    if (!en) return null;
    if (lang === "en") return {title:en[0],detail:en[1],linkText:en[2]};
    const g = guideTranslations[topic];
    if (g) return {title:g[lang === "hi" ? 0 : 1],detail:g[lang === "hi" ? 2 : 3],linkText:g[lang === "hi" ? 4 : 5]};
    return {title:en[0],detail:en[1],linkText:en[2]};
}

// Text-to-speech follows the selected language and uses an installed matching voice when available.
function readPage() {
    if (!("speechSynthesis" in window)) {
        const msg = currentLanguage === "hi" ? "इस ब्राउज़र में पाठ को आवाज़ में पढ़ने की सुविधा उपलब्ध नहीं है। कृपया क्रोम आज़माएँ।" : currentLanguage === "mr" ? "या ब्राउझरमध्ये मजकूर मोठ्याने वाचण्याची सुविधा उपलब्ध नाही. कृपया क्रोम वापरून पाहा." : "Text-to-speech is not supported in this browser. Please try Chrome.";
        alert(msg); return;
    }
    window.speechSynthesis.cancel();
    const mainText = document.querySelector("main").innerText;
    const speech = new SpeechSynthesisUtterance(mainText);
    const locale = currentLanguage === "hi" ? "hi-IN" : currentLanguage === "mr" ? "mr-IN" : "en-IN";
    speech.lang = locale; speech.rate = 0.88; speech.pitch = 1;
    const voices = window.speechSynthesis.getVoices();
    speech.voice = voices.find(v => v.lang.toLowerCase() === locale.toLowerCase()) || voices.find(v => v.lang.toLowerCase().startsWith(currentLanguage)) || null;
    window.speechSynthesis.speak(speech);
}
document.getElementById("readBtn").addEventListener("click", readPage);
document.getElementById("speakBtn").addEventListener("click", readPage);
document.getElementById("pauseBtn").addEventListener("click", () => {
    const speaker = window.speechSynthesis;
    if (!speaker.speaking) readPage(); else if (speaker.paused) speaker.resume(); else speaker.pause();
});
document.getElementById("stopBtn").addEventListener("click", () => window.speechSynthesis.cancel());

